INSERT INTO public.freelancer_resumes
  (telegram_id, first_name, last_name, phone, city, about, marketplaces, preferred_schedule, hourly_rate, metro_stations, status)
VALUES
  (990000001, 'Анна', 'Ковалёва', '+79991000000', 'Москва', 'Год работала на пункте выдачи WB: приёмка, выдача, возвраты. Спокойно объясняю клиентам про брак и сроки.', ARRAY['WB']::text[], '5/2', 450, ARRAY['Кропоткинская','Арбатская']::text[], 'active'),
  (990000002, 'Дмитрий', 'Соколов', '+79991000001', 'Москва', 'Опыт 2 года на ПВЗ. Быстро разбираю поставку, знаю кассу и терминал. Готов на подмены в выходные.', ARRAY['WB','Ozon']::text[], '2/2', 500, ARRAY['Беговая','Лубянка']::text[], 'active'),
  (990000003, 'Марина', 'Ильина', '+79991000002', 'Санкт-Петербург', 'Работала в Ozon Rocket. Аккуратная приёмка, слежу за возвратами и сроками хранения.', ARRAY['Ozon']::text[], '5/2', 480, ARRAY['Площадь Восстания','Гостиный двор']::text[], 'active'),
  (990000004, 'Игорь', 'Петров', '+79991000003', 'Москва', 'Три года в логистике, последний год — ПВЗ Яндекс Маркета. Могу выходить в ночь.', ARRAY['Яндекс Маркет']::text[], 'сменный', 520, ARRAY['Аэропорт','Краснопресненская']::text[], 'active'),
  (990000005, 'Ольга', 'Новикова', '+79991000004', 'Санкт-Петербург', 'Знаю оба интерфейса — WB и Ozon. Легко нахожу общий язык с клиентами, без конфликтов.', ARRAY['WB','Ozon']::text[], '2/2', 470, ARRAY['Фрунзенская','Владимирская']::text[], 'active'),
  (990000006, 'Сергей', 'Волков', '+79991000005', 'Москва', 'Ищу стабильную подработку рядом с домом. Опыт полгода, всему учусь быстро.', ARRAY['WB']::text[], '5/2', 430, ARRAY['Красные ворота','Боровская']::text[], 'active'),
  (990000007, 'Елена', 'Морозова', '+79991000006', 'Москва', 'Опыт 4 года, была старшей смены. Могу закрыть точку под ключ и обучить новичка.', ARRAY['Ozon','Яндекс Маркет']::text[], 'гибкий', 550, ARRAY['Красные ворота','Динамо']::text[], 'active'),
  (990000008, 'Артём', 'Лебедев', '+79991000007', 'Санкт-Петербург', 'Универсал: работал на всех трёх маркетплейсах. Инвентаризация, отчётность, приёмка.', ARRAY['WB','Ozon','Яндекс Маркет']::text[], '2/2', 600, ARRAY['Петроградская','Чёрная речка']::text[], 'active'),
  (990000009, 'Юлия', 'Захарова', '+79991000008', 'Москва', 'Студентка, свободна по выходным. Была на ПВЗ летом — знаю приёмку и выдачу.', ARRAY['WB']::text[], 'выходные', 460, ARRAY['Красносельская','Завод имени Сталина']::text[], 'active'),
  (990000010, 'Павел', 'Крылов', '+79991000009', 'Санкт-Петербург', 'Два года на пункте выдачи, без опозданий и нареканий. Готов подменять коллег.', ARRAY['Ozon']::text[], '5/2', 490, ARRAY['Пушкинская','Садовая']::text[], 'active');
