  (990000025, 'permanent', 'Санкт-Петербург', 'Невский пр-т, д. 90', ARRAY['WB']::text[], ARRAY['Гостиный двор']::text[], 41000, '5/2', 'Центр города, высокий трафик. Ищем внимательного сотрудника.', 'active'),
  (990000021, 'permanent', 'Санкт-Петербург', 'ул. Садовая, д. 32', ARRAY['Ozon','WB']::text[], ARRAY['Комендантский аэродром']::text[], 46000, '2/2', 'Два маркетплейса в одном пункте. Обучаем с нуля.', 'active'),
  (990000022, 'permanent', 'Москва', 'Кутузовский пр-т, д. 5', ARRAY['WB']::text[], ARRAY['Комсомольская']::text[], 50000, 'сменный', 'Оплата выше рынка за счёт объёма. Нужен опыт от полугода.', 'active'),
  (990000023, 'permanent', 'Москва', 'ул. Академика Королёва, д. 9', ARRAY['Ozon']::text[], ARRAY['Кокошкино']::text[], 43000, '5/2', 'Рядом метро, удобная логистика. Испытательный срок 2 недели.', 'active'),
